/usr/bin/zsh -lc "mkdir -p evidence && node --check app.js && node --input-type=module <<'JS'
import puppeteer from '/tmp/qs-hf-probe/node_modules/puppeteer-core/lib/puppeteer/puppeteer-core.js';
import assert from 'node:assert/strict';
const browser = await puppeteer.launch({executablePath:'/home/djn12313/.cache/ms-playwright/chromium_headless_shell-1234/chrome-headless-shell-linux64/chrome-headless-shell',headless:true,args:['--no-sandbox','--disable-dev-shm-usage']});
try {
 const page=await browser.newPage();
 const errors=[]; const external=[];
 page.on('pageerror',e=>errors.push(e.message));
 await page.setRequestInterception(true);
 page.on('request',r=>{if(r.url().startsWith('file:'))r.continue();else{external.push(r.url());r.abort();}});
 for(const [name,width,height] of [['wide',1280,900],['narrow',390,844]]){
  await page.setViewport({width,height});
  await page.goto('file:///tmp/qs-frontend-trial-7Os9cs/index.html');
  assert.equal(await page.title(),'Membership — Northstar Museum');
  assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true,name+' overflow');
  for(const id of ['site-header','site-footer','membership-panel','membership-title','price','member-count','annual-visits','founded','join-form','member-email','join-button','form-message','details-link']) assert.equal(await page."'$$eval('"'#'+id,e=>e.length),1,id);
  assert.deepEqual(await page.evaluate(()=>['member-count','annual-visits','founded'].map(id=>document.getElementById(id).textContent)),['10,000','50,000','2020']);
  assert.equal(await page."'$eval('"'#price',e=>e.textContent),'"'$100 / year'"');
  assert.equal(await page."'$eval('"'#details-link',e=>e.getAttribute('href')),'/membership/family');
  assert.equal(await page."'$eval('"'#join-form',e=>e.getAttribute('action')),'/join/checkout?plan=family');
  assert.equal(await page."'$eval('"'body',e=>getComputedStyle(e).fontFamily),'Georgia, \"Times New Roman\", serif');
  await page.screenshot({path:'evidence/'+name+'.png',fullPage:true});
  await page.keyboard.press('Tab');
  assert.equal(await page.evaluate(()=>document.activeElement.className),'skip-link');
  assert.equal(await page.evaluate(()=>getComputedStyle(document.activeElement).outlineStyle),'solid');
  await page.focus('#join-button'); await page.keyboard.press('Enter');
  assert.equal(await page.evaluate(()=>window.__events.length),0);
  assert.equal(await page.evaluate(()=>document.activeElement.id),'member-email');
  await page.type('#member-email','invalid');
  await page.focus('#join-button'); await page.keyboard.press('Enter');
  assert.equal(await page.evaluate(()=>window.__events.length),0);
  await page."'$eval('"'#member-email',e=>e.value='');
  await page.focus('#member-email'); await page.type('#member-email','visitor@example.com');
  await page.keyboard.press('Tab');
  assert.equal(await page.evaluate(()=>document.activeElement.id),'join-button');
  await page.keyboard.press('Enter');
  assert.equal(await page."'$eval('"'#form-message',e=>e.textContent),'Ready to continue with Family membership.');
  assert.deepEqual(await page.evaluate(()=>window.__events),[{name:'join_started',plan:'family'}]);
  assert.equal(page.url(),'file:///tmp/qs-frontend-trial-7Os9cs/index.html');
  assert.equal(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth),true,name+' success overflow');
  await page.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);
  assert.equal(await page.evaluate(()=>matchMedia('(prefers-reduced-motion: reduce)').matches),true);
  console.log(name+': PASS — content, IDs, routes, typography, overflow, keyboard focus, invalid and valid form, analytics, reduced motion');
 }
 assert.deepEqual(errors,[]);assert.deepEqual(external,[]);
 console.log('PASS — no browser errors; no external requests; screenshots: evidence/wide.png, evidence/narrow.png');
} finally {await browser.close();}
JS"

